// itself evidence that a run can resolve it — the failure that would hide here
// is a kind registered under a nil constructor, which only shows up when a run
// asks for a resolver.
func TestRegisteredKindsAreConstructedForARun(t *testing.T) {
	t.Parallel()

	resolver := source.Default.NewResolver(source.RunOptions{})
	require.NotNil(t, resolver)

	for _, kind := range source.Default.Kinds() {
		assert.NotNil(t, resolver.Kind(kind), "no resolver constructed for kind %q", kind)
	}
}

